BEGIN TRAN;
  UPDATE Acct SET Bal -= 100 WHERE Id = 1;
  SAVE TRAN s1;
  UPDATE Acct SET Bal += 100 WHERE Id = 2;
COMMIT;  -- or ROLLBACK TRAN s1;

WITH Recent AS (
  SELECT * FROM Orders WHERE Date > '2024-01-01')
SELECT * FROM Recent WHERE Total > 100;

MERGE Target t USING Source s ON t.Id = s.Id
WHEN MATCHED THEN UPDATE SET t.Val = s.Val
WHEN NOT MATCHED THEN INSERT (Id, Val) VALUES (s.Id, s.Val);

SELECT Name, Salary,
  ROW_NUMBER() OVER (PARTITION BY Dept ORDER BY Salary DESC) AS rn
FROM Emp;

SELECT Salary FROM (
  SELECT Salary, DENSE_RANK() OVER (ORDER BY Salary DESC) r
  FROM Emp) t WHERE r = @N;
